cmn_relative_duration.script:
// Perform relative duration calculation using the 'calculator' variable (which is a DurationCalculator object)

(function() {

	var startValue = current.getValue('date_time_became_aware');
	var startTime = new GlideDateTime(startValue);

	var durationDays = Number(gs.getProperty('x_1776078_cyber_0.sla.ndb_assessment_days'));
	startTime.addDaysUTC(durationDays);

	var slaCreated = new GlideDateTime(calculator.startDateTime);
	if (startTime.before(slaCreated)) {
		slaCreated.addSeconds(1);
		startTime = slaCreated;
	}

    calculator.endDateTime = startTime;
    calculator.calcScheduleDuration();
})();
